  roof(g, [3, 12, 11, 24], "townhouse", { y: 18, front: "north", overhang: 1, material: SLATE, trim: "stone_brick", keep: [bVolume, bFace, { from: [10, 18, 18], to: [10, 28, 19] }, ladderA] });

